export const sendChatMessage = async (
  history: {role: string, text: string}[], 
  newMessage: string,
  systemInstruction: string
) => {
  console.log("AI Chat is currently disabled.");
  return "AI Chat is disabled.";
};
```

## components/DataContext.tsx

I moved the "System Instruction" text directly into this file so it doesn't need to import anything from `gemini.ts`. This breaks the connection to the problematic file.

